# Generated by build.py from recipe.yml for recipe ftp-retry-after-a-refused-login. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'plain', 'slow', 'strict' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'slow/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'strict/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--user', 'app:s3cret', '--allow-plaintext-auth', '--directory', 'site', '--fault', '"refuse-login;times=1"', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --no-progress-meter -u app:s3cret --retry 3 --retry-all-errors -w "%{exitcode} %{num_retries}\n" ftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
